#include <stdlib.h>

typedef struct {
    int* parent;
    int* size;
    int n;
} UnionFind;

UnionFind* ufCreate(int n) {
    UnionFind* uf = (UnionFind*)malloc(sizeof(UnionFind));
    uf->parent = (int*)malloc(n * sizeof(int));
    uf->size = (int*)malloc(n * sizeof(int));
    uf->n = n;
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->size[i] = 1;
    }
    return uf;
}

int ufFind(UnionFind* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = ufFind(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void ufUnion(UnionFind* uf, int a, int b) {
    int rootA = ufFind(uf, a);
    int rootB = ufFind(uf, b);
    if (rootA != rootB) {
        if (uf->size[rootA] < uf->size[rootB]) {
            int tmp = rootA;
            rootA = rootB;
            rootB = tmp;
        }
        uf->parent[rootB] = rootA;
        uf->size[rootA] += uf->size[rootB];
    }
}

void ufFree(UnionFind* uf) {
    free(uf->parent);
    free(uf->size);
    free(uf);
}

int cmpInt(const void* a, const void* b) {
    return (*(int*)a) - (*(int*)b);
}

int minMalwareSpread(int** graph, int graphSize, int* graphColSize, int* initial, int initialSize){
    int n = graphSize;
    // Sort initial to ensure lowest index tie-break
    qsort(initial, initialSize, sizeof(int), cmpInt);

    // Build Union-Find for connected components
    UnionFind* uf = ufCreate(n);
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            if (graph[i][j] == 1) {
                ufUnion(uf, i, j);
            }
        }
    }

    // Count size of each component
    // uf->size[root] already stores size of component root

    // Count how many initial infected nodes in each component
    int* infectedCount = (int*)calloc(n, sizeof(int));
    for (int i = 0; i < initialSize; i++) {
        int root = ufFind(uf, initial[i]);
        infectedCount[root]++;
    }

    // For each node in initial, if it is the only infected node in its component,
    // removing it will save the whole component from infection.
    // Choose the node that saves the largest component size.
    // If no such node, return the smallest index in initial.

    int result = initial[0];
    int maxSaved = -1;
    for (int i = 0; i < initialSize; i++) {
        int node = initial[i];
        int root = ufFind(uf, node);
        if (infectedCount[root] == 1) {
            // This node is the only infected in its component
            if (uf->size[root] > maxSaved) {
                maxSaved = uf->size[root];
                result = node;
            }
        }
    }

    ufFree(uf);
    free(infectedCount);
    return result;
}

